    for ra, rb in zip(horizontal, horizontal[1:]):
        for ca, cb in zip(vertical, vertical[1:]):
            if rb - ra < 4 or cb - ca < 4:
                continue
            pattern = [row[ca + 2:cb - 1] for row in out[ra + 2:rb - 1]]
            ph, pw = len(pattern), len(pattern[0])
            best_key = None
            best_values = None
            best_period = None
            for dy in range(1, ph + 1):
                for dx in range(1, pw + 1):
                    values = {}
                    errors = 0
                    for y in range(dy):
                        for x in range(dx):
                            cells = [pattern[yy][xx]
                                     for yy in range(y, ph, dy)
                                     for xx in range(x, pw, dx)]
                            value, count = Counter(cells).most_common(1)[0]
                            values[y, x] = value
                            errors += len(cells) - count
                    key = (errors, dy + dx, dy * dx)
                    if best_key is None or key < best_key:
                        best_key = key
                        best_values = values
                        best_period = (dy, dx)
            dy, dx = best_period
            for y in range(ph):
                for x in range(pw):
                    out[ra + 2 + y][ca + 2 + x] = best_values[y % dy, x % dx]
    return out
