from collections import Counter

def transform(grid):
    result = [row[:] for row in grid]

    def repair(top, left, bottom, right):
        source = [row[left:right] for row in grid[top:bottom]]
        height = len(source)
        width = len(source[0])
        choices = []
        for period_y in range(1, height + 1):
            for period_x in range(1, width + 1):
                tile = [[0] * period_x for _ in range(period_y)]
                mismatches = 0
                for ty in range(period_y):
                    for tx in range(period_x):
                        observations = [source[y][x]
                                        for y in range(ty, height, period_y)
                                        for x in range(tx, width, period_x)]
                        value, frequency = Counter(observations).most_common(1)[0]
                        tile[ty][tx] = value
                        mismatches += len(observations) - frequency
                choices.append((mismatches, period_y + period_x,
                                period_y * period_x, period_y, period_x, tile))
        _, _, _, period_y, period_x, tile = min(choices, key=lambda item: item[:3])
        for y in range(height):
            for x in range(width):
                result[top + y][left + x] = tile[y % period_y][x % period_x]

    background = grid[0][0]
    row_separators = [y for y, row in enumerate(grid)
                      if all(value == background for value in row)]
    column_separators = [x for x in range(len(grid[0]))
                         if all(grid[y][x] == background
                                for y in range(len(grid)))]

    for top_separator, bottom_separator in zip(row_separators, row_separators[1:]):
        for left_separator, right_separator in zip(column_separators,
                                                   column_separators[1:]):
            if bottom_separator - top_separator > 3 and right_separator - left_separator > 3:
                repair(top_separator + 2, left_separator + 2,
                       bottom_separator - 1, right_separator - 1)
    return result
